  "article_faq_title": "Preguntas Frecuentes",
  "blog_cta_explore_title": "Explore el caso completo en nuestro Portafolio",
  "blog_cta_explore_desc": "Conozca detalles técnicos, capturas y soluciones implementadas por el equipo de tecnología y estrategia de CONEXUS.",
  "blog_cta_view_case": "Ver Caso en el Portafolio",
